import math
from functools import lru_cache

# Define a helper function to compute Fibonacci modulo p
def fibonacci_mod_p(n, p):
    if n < 0:
        return 0

    @lru_cache(maxsize=None)
    def fib(n, p):
        if n <= 1:
            return n

        a, b = 0, 1
        for _ in range(2, n+1):
            a, b = b, (a + b) % p
        return b

    return fib(n, p)

# Example usage
print(fibonacci_mod_p(1, 5))       # Output: (1, 5)
print(fibonacci_mod_p(4, 5))       # Output: (3, 5)
print(fibonacci_mod_p(5, 7))       # Output: (2, 7)

